<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><title>Salary Payslip - {{ $payroll->employee_name }}</title>@include('pdf.style')</head><body><div class="header"><div class="eyebrow">{{ $payroll->company_name }}</div><h1>Salary payslip</h1><span style="color:#b9d3cd">{{ $payroll->employment_type === 'own' ? 'Own employee - Fixed monthly salary' : 'Rental manpower - Hourly payroll' }}</span></div><table class="two-column"><tr><td><strong style="font-size:14px">{{ $payroll->employee_name }}</strong><br>{{ $payroll->designation_name }}<br><span class="meta">Iqama: {{ $payroll->iqama_number }}</span></td><td style="text-align:right"><strong>{{ \Carbon\Carbon::createFromFormat('!Y-m', $payroll->month)->format('F Y') }}</strong><br><span class="meta">SLIP-{{ str_pad($payroll->id, 5, '0', STR_PAD_LEFT) }}</span><br><span class="badge">{{ strtoupper($payroll->status) }}</span></td></tr></table><table class="paytable"><tr><td>{{ $payroll->employment_type === 'own' ? 'Fixed monthly base salary' : 'Regular pay ('.\App\Services\Pay::decimal($payroll->regular_units).' hours)' }}</td><td class="amount">SAR {{ \App\Services\Pay::money($payroll->regular_pay_cents) }}</td></tr><tr><td>Overtime ({{ \App\Services\Pay::decimal($payroll->overtime_units) }} hours)</td><td class="amount">SAR {{ \App\Services\Pay::money($payroll->overtime_pay_cents) }}</td></tr><tr><td>Allowances</td><td class="amount">+ {{ \App\Services\Pay::money($payroll->allowance_cents) }}</td></tr><tr><td>Deductions</td><td class="amount">- {{ \App\Services\Pay::money($payroll->deduction_cents) }}</td></tr></table><table class="total"><tr><td>Net salary payable</td><td class="amount">SAR {{ \App\Services\Pay::money($payroll->net_pay_cents) }}</td></tr></table>@if($payroll->notes)<div class="note longtext">{{ $payroll->notes }}</div>@endif<h2>Approved hours included</h2><table class="hours"><thead><tr><th>Date</th><th>Regular hours</th><th>OT hours</th><th>Hourly SAR</th><th>OT multiplier</th></tr></thead>